    color: #e8e8e8;
    background-color: #2b2b2b;
    padding: 20px 24px;
    line-height: 1.7;
}

ruby { font-family: "Hiragino Kaku Gothic Pro", "Noto Sans JP", "Meiryo", "MS PGothic", sans-serif; ruby-align: center; }
rt { font-size: 0.5em; color: #e8e8e8; }

